const snowRand=i=>{const x=Math.sin(i*79.31+13.8)*43758.5;return x-Math.floor(x)};
export class SnowScene {
 constructor(){this.time=0;this.flakes=[];this.chips=[];this.loads=new Map();this.masks=new WeakMap();this.backdrop=null;this.bound=null;this.branchSites=[]}
 resize(w,h,ground){this.w=w;this.h=h;this.ground=ground;this.backdrop=null;this.flakes=Array.from({length:Math.min(210,Math.round(w*h/3800))},(_,i)=>({x:snowRand(i)*w,y:snowRand(i+600)*h,z:snowRand(i+300),phase:i*2.4}));this.chips=[]}
 bind(sim){if(this.bound===sim)return;this.bound=sim;this.loads.clear();this.chips=[];this.branchSites=[];if(sim.kind==='maple'){for(const b of sim.branches){if(b.parent<0||b.width<1.4)continue;for(const t of [.3,.62]){const a=sim.point(b,t-.08),p=sim.point(b,t+.08);if(Math.abs(p.x-a.x)<Math.abs(p.y-a.y)*.55)continue;this.branchSites.push({branch:b,t,amount:1,x:(a.x+p.x)/2,y:(a.y+p.y)/2})}}return}for(const l of sim.leaves)if(l.id%11===0&&l.layer!=='back')this.loads.set(l,1)}
 reset(){this.loads.clear();this.chips=[];this.bound=null;this.time=0;this.branchSites=[]}
 keepLeaf(l){return l.id%251===19}
 branchSnow(ctx,sim){ctx.save();ctx.lineCap='round';for(const site of this.branchSites){const b=site.branch,t=site.t,p=sim.point(b,t),a=sim.point(b,t-.1),z=sim.point(b,t+.12),offset=b.width*.45*Math.pow(1-t,.8)+.6;site.x=p.x;site.y=p.y-offset;if(site.amount<=.02)continue;ctx.globalAlpha=site.amount;ctx.strokeStyle='#b8ccd7';ctx.lineWidth=2+b.width*.16;ctx.beginPath();ctx.moveTo(a.x,a.y-offset+.6);ctx.quadraticCurveTo(p.x,p.y-offset-1,z.x,z.y-offset);ctx.stroke();ctx.strokeStyle='#f5f8f8';ctx.lineWidth=1.4+b.width*.12;ctx.beginPath();ctx.moveTo(a.x,a.y-offset-.2);ctx.quadraticCurveTo(p.x,p.y-offset-1.5,z.x,z.y-offset-.3);ctx.stroke()}ctx.restore()}
 touch(a,b,reduced=false){const dx=b.x-a.x,dy=b.y-a.y,n=dx*dx+dy*dy;for(const site of this.branchSites){const t=n?Math.max(0,Math.min(1,((site.x-a.x)*dx+(site.y-a.y)*dy)/n)):0;if(site.amount<.4||Math.hypot(site.x-a.x-t*dx,site.y-a.y-t*dy)>42)continue;site.amount=0;if(!reduced)for(let i=0;i<5&&this.chips.length<120;i++)this.chips.push({x:site.x+(i-2)*3,y:site.y,vx:(snowRand(i+site.t*30)-.5)*50,vy:-10-i*3,r:1.2+snowRand(i+7)*1.9,age:0})}for(const [l,amount] of this.loads){if(amount<.4||l.state!=='attached')continue;const t=n?Math.max(0,Math.min(1,((l.x-a.x)*dx+(l.y-a.y)*dy)/n)):0;if(Math.hypot(l.x-a.x-t*dx,l.y-a.y-t*dy)>45)continue;this.loads.set(l,0);if(!reduced)for(let i=0;i<4&&this.chips.length<120;i++)this.chips.push({x:l.x,y:l.y-l.size*.25,vx:(snowRand(l.id+i)-.5)*65+dx*.1,vy:-15-snowRand(i+30)*30,r:1.3+snowRand(i+l.id)*2,age:0})}}
 step(dt,reduced=false){if(reduced){this.chips=[];return}this.time+=dt;for(const site of this.branchSites)site.amount=Math.min(1,site.amount+dt*.018);for(const p of this.flakes){p.x+=(7+Math.sin(this.time*.5+p.phase)*(7+p.z*9))*dt;p.y+=(15+p.z*32)*dt;if(p.y>this.h+8){p.y=-8;p.x=snowRand(p.phase+this.time)*this.w}if(p.x>this.w+10)p.x=-8;if(p.x< -10)p.x=this.w+8}for(const p of this.chips){p.age+=dt;p.vy+=85*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.exp(-dt*.7)}this.chips=this.chips.filter(p=>p.age<3&&p.y<770);for(const [l,v] of this.loads)if(l.state==='attached'&&v<1)this.loads.set(l,Math.min(1,v+dt*.025))}
 mask(im,angle){let variants=this.masks.get(im);if(!variants){variants=[];this.masks.set(im,variants)}const bucket=((Math.round(angle/(Math.PI/4))%8)+8)%8;if(variants[bucket])return variants[bucket];const c=document.createElement('canvas');c.width=c.height=96;const g=c.getContext('2d'),a=bucket*Math.PI/4;g.drawImage(im,0,0,96,96);g.globalCompositeOperation='source-in';const grad=g.createLinearGradient(48-Math.sin(a)*42,48-Math.cos(a)*42,48+Math.sin(a)*42,48+Math.cos(a)*42);grad.addColorStop(0,'rgba(246,250,250,.95)');grad.addColorStop(.29,'rgba(238,245,248,.86)');grad.addColorStop(.45,'rgba(218,232,239,.15)');grad.addColorStop(.59,'rgba(222,236,243,0)');g.fillStyle=grad;g.fillRect(0,0,96,96);variants[bucket]=c;return c}
 coat(ctx,l,im,w,h,species){const amount=this.loads.get(l);if(!amount||l.state!=='attached')return;const alpha=ctx.globalAlpha;ctx.globalAlpha*=amount;ctx.drawImage(this.mask(im,l.angle),-w*(species==='willow'?.34:.5),species==='willow'?-h*.1:species==='jacaranda'?-h*.5:-h*.85,species==='willow'?w*.68:w,h);ctx.globalAlpha=alpha}
 debris(ctx){ctx.save();for(const p of this.chips){ctx.globalAlpha=Math.max(0,1-p.age/3);ctx.fillStyle='#f3f8fa';ctx.beginPath();ctx.ellipse(p.x,p.y,p.r,p.r*.65,p.age,0,Math.PI*2);ctx.fill()}ctx.restore()}
 background(ctx,reduced=false){if(!this.backdrop){const c=document.createElement('canvas');c.width=this.w;c.height=this.h;const g=c.getContext('2d'),w=this.w,h=this.h,root=this.ground;const sky=g.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#9dB3c0');sky.addColorStop(.55,'#d1dfe3');sky.addColorStop(1,'#edf2f0');g.fillStyle=sky;g.fillRect(0,0,w,h);g.save();g.filter='blur(13px)';g.fillStyle='rgba(106,137,149,.13)';for(let i=0;i<16;i++){g.beginPath();g.ellipse(i*w/14,root-45-snowRand(i)*55,25+snowRand(i+80)*w*.04,65+snowRand(i+30)*60,0,0,Math.PI*2);g.fill()}g.restore();const floor=g.createLinearGradient(0,root-50,0,h);floor.addColorStop(0,'rgba(237,244,244,0)');floor.addColorStop(.32,'rgba(232,241,242,.86)');floor.addColorStop(1,'#f3f6f3');g.fillStyle=floor;g.fillRect(0,root-50,w,h-root+50);this.backdrop=c}ctx.drawImage(this.backdrop,0,0,this.w,this.h);this.drawFlakes(ctx,0,reduced)}
 drawFlakes(ctx,front,reduced=false){if(reduced)return;ctx.save();for(const p of this.flakes){if((p.z>.65?1:0)!==front)continue;ctx.globalAlpha=.3+p.z*.48;ctx.fillStyle='#f8fcff';ctx.beginPath();ctx.arc(p.x,p.y,.55+p.z*1.65,0,Math.PI*2);ctx.fill()}ctx.restore()}
 foreground(ctx,reduced=false){this.drawFlakes(ctx,1,reduced)}
}
